const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reveals=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');reveals.unobserve(e.target)}}),{threshold:.08});
function observe(){ $$('.reveal:not(.visible)').forEach(el=>reveals.observe(el)) }observe();
const menu=$('#menu'),nav=$('#nav');function closeMenu(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Ouvrir le menu');menu.textContent='☰';nav.classList.remove('open')}menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu');menu.textContent=open?'×':'☰';nav.classList.toggle('open',open)});$$('#nav a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
let scrollFrame=false;const sections=$$('main>section[id]');function scrollUpdate(){scrollFrame=false;const max=document.documentElement.scrollHeight-innerHeight;$('.progress').style.transform=`scaleX(${max>0?scrollY/max:0})`;let active=sections[0].id;for(const s of sections)if(s.getBoundingClientRect().top<innerHeight*.38)active=s.id;$$('#nav a').forEach(a=>{const current=a.hash===`#${active}`;a.classList.toggle('active',current);if(current)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}addEventListener('scroll',()=>{if(!scrollFrame){requestAnimationFrame(scrollUpdate);scrollFrame=true}},{passive:true});scrollUpdate();
function theme(value){document.documentElement.dataset.theme=value;$('#theme').textContent=value==='dark'?'☼':'☾';$('#theme').setAttribute('aria-label',value==='dark'?'Activer le thème clair':'Activer le thème sombre');$('meta[name="theme-color"]').content=value==='dark'?'#03070D':'#F8FAFC'}try{theme(localStorage.getItem('hl-orbit-theme')==='light'?'light':'dark')}catch{theme('dark')}$('#theme').addEventListener('click',()=>{const value=document.documentElement.dataset.theme==='dark'?'light':'dark';theme(value);try{localStorage.setItem('hl-orbit-theme',value)}catch{}});
const stacks={frontend:{label:'Frontend',items:[['⚛','React','Interfaces','Composants et interfaces web avec React.','#d4d4d4'],['JS','JavaScript','Interactions','Logique et interactions côté navigateur.','#d4d4d4'],['5','HTML5','Structure','Structure sémantique des pages web.','#a3a3a3'],['#','CSS3','Présentation','Mise en page, responsive et styles des interfaces.','#a3a3a3']]},backend:{label:'Backend',items:[['Py','Python','Langage','Développement applicatif et backend en Python.','#d4d4d4'],['dj','Django','Framework','Développement d’applications web avec Django.','#d4d4d4'],['J','Java / JEE','Applications','Applications en Java et Java Enterprise.','#a3a3a3'],['C#','C# / .NET','Applications','Applications de gestion avec l’écosystème .NET.','#a3a3a3'],['L','PHP / Laravel','Web','Applications web et e-commerce avec Laravel.','#a3a3a3'],['N','Node.js','JavaScript serveur','Développement côté serveur en JavaScript.','#d4d4d4']]},database:{label:'Database',items:[['≋','MySQL','Base relationnelle','Gestion des données relationnelles avec MySQL.','#a3a3a3'],['SQL','SQL','Requêtes','Requêtes et manipulation de données relationnelles.','#a3a3a3'],['DB','SGBD','Modélisation','Conception et gestion des données applicatives.','#a3a3a3']]},tools:{label:'Tools',items:[['⑂','Git','Notions','Notions de gestion de versions avec Git.','#a3a3a3'],['↻','Agile','Méthodes','Méthodes de travail Agile et amélioration itérative.','#a3a3a3']]},devops:{label:'DevOps',items:[['>_','Linux','Systèmes','Compétences Linux et certification Coursera.','#d4d4d4']]},other:{label:'Autres technologies',items:[['C','C','Programmation','Programmation et fondamentaux en langage C.','#a3a3a3'],['++','C++','Programmation','Programmation C++ et certification Coursera.','#a3a3a3'],['API','Django REST','APIs','Développement d’une plateforme avec Django REST Framework.','#a3a3a3']]}};
const panel=$('#stack-panel');
$('.stack-tabs').remove();panel.removeAttribute('role');panel.removeAttribute('tabindex');panel.dataset.rabatStack='true';panel.classList.add('rabat-skills');
panel.innerHTML=Object.entries(stacks).map(([id,s],i)=>`<article class="rabat-skill-card"><header><span class="skill-number">0${i+1}</span><h3>${s.label}</h3><span aria-hidden="true">↗</span></header><div class="rabat-tech-list">${s.items.map(([symbol,name,role,detail])=>`<button class="tech" type="button" data-detail="${escapeHTML(detail)}"><span class="tech-symbol" aria-hidden="true">${symbol}</span><span><strong>${name}</strong><small>${role}</small></span></button>`).join('')}</div></article>`).join('');
function techDetail(e){const b=e.target.closest('[data-detail]');if(b)$('.stack-detail').textContent=b.dataset.detail}['pointerover','focusin','click'].forEach(event=>panel.addEventListener(event,techDetail));

function mockup(p){if(p.cover)return `<div class="art project-cover"><img src="${escapeHTML(p.cover)}" alt="Capture du projet ${escapeHTML(p.title)}" loading="lazy" decoding="async"></div>`;let content;if(p.visual==='tasks')content=`<div class="mock-stats"><div><small>CRÉER</small><b>＋</b></div><div><small>AFFECTER</small><b>↗</b></div><div><small>SUIVRE</small><b>✓</b></div></div><div class="mock-columns">${['À faire','En cours','Terminé'].map((s,i)=>`<div class="mock-column"><small>${s}</small><div class="mock-task"><em>${['Interface','Backend','Validation'][i]}</em><b>${['Concevoir les écrans','Développer les vues','Tester le parcours'][i]}</b><i></i></div><div class="mock-task"><b>Suivi des tâches</b><i></i></div></div>`).join('')}</div>`;else if(['courses','shop'].includes(p.visual))content=`<div class="mock-courses">${(p.visual==='courses'?['Développement web','Python & Django','JavaScript']:['Au quotidien','Produits écologiques','Notre sélection']).map((s,i)=>`<div><div class="course-cover">${['⌘','✳','↗'][i]}</div><b>${s}</b></div>`).join('')}</div><div class="mock-stats"><div><small>DÉCOUVRIR</small><b>↗</b></div><div><small>EXPLORER</small><b>＋</b></div></div>`;else if(p.visual==='weather')content='<div style="font-size:36px;padding-top:17px;color:#a3a3a3">☀ <span style="font-size:12px">Votre météo</span></div><div class="mock-chart"><i style="height:40%"></i><i style="height:70%"></i><i style="height:90%"></i><i style="height:65%"></i><i style="height:45%"></i></div>';else content=`<div class="mock-stats"><div><small>VUE D’ENSEMBLE</small><b>◎</b></div><div><small>GESTION</small><b>↗</b></div><div><small>SUIVI</small><b>✓</b></div></div><div class="mock-chart">${[35,65,45,90,70,80,60,95].map(h=>`<i style="height:${h}%"></i>`).join('')}</div>`;return `<div class="art" style="--art-bg:${p.bg};--glow:${p.glow}" role="img" aria-label="Illustration conceptuelle de ${escapeHTML(p.title)}"><div class="art-label"><span>ILLUSTRATION D’INTERFACE</span><span>${p.code}</span></div><div class="mock" aria-hidden="true"><div class="mock-bar"><i></i><i></i><i></i><small>CONCEPT UI / ${p.code}</small></div><div class="mock-layout"><div class="mock-sidebar"><strong>${p.mark}</strong><i></i><i></i><i></i><i></i></div><div class="mock-main"><div class="mock-title">${p.screen}<span>${p.visual==='tasks'?'+ Nouvelle tâche':'Vue d’ensemble'}</span></div><div class="mock-sub">${p.visual==='tasks'?'Organiser. Affecter. Faire avancer.':'Une interface pensée pour le quotidien.'}</div>${content}</div></div></div></div>`}
const grid=$('#projects');function renderProjects(filter='all'){const list=PORTFOLIO_PROJECTS.filter(p=>filter==='all'||p.filters.includes(filter));grid.innerHTML=list.map((p,i)=>`<article class="project work-slide" data-work-index="${i}"><div class="work-visual"><span class="work-visual-index">${String(i+1).padStart(2,'0')}</span>${mockup(p)}<span class="work-visual-caption">${p.visual==='tasks'?'REACT + DJANGO / APPLICATION MÉTIER':p.category.toUpperCase()+' / EXPLORATION'}</span></div><div class="project-info"><div class="project-meta"><span>${p.featured?'FEATURED PROJECT':p.category.toUpperCase()}</span><span>${p.context}</span></div><h3>${p.title}</h3><p class="copy">${p.description}</p><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div><dl class="work-specs"><div><dt>ANNÉE</dt><dd>${p.id==='tasks'?'2025 — 2026':'Non renseignée'}</dd></div><div><dt>RÔLE</dt><dd>${p.filters.includes('fullstack')?'Développement Full Stack':'Développement'}</dd></div></dl>${p.github?`<a class="open-project" data-project="${p.id}" href="${escapeHTML(p.github)}" target="_blank" rel="noopener noreferrer">Voir le projet <span>→</span></a>`:`<button class="open-project" data-project="${p.id}">Voir le projet <span>→</span></button>`}</div></article>`).join('');window.dispatchEvent(new Event('portfolio:projects'));}renderProjects();$('#project-total').textContent=$('#filter-total').textContent=String(PORTFOLIO_PROJECTS.length).padStart(2,'0');$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderProjects(b.dataset.filter)}));
const projectDialog=$('#project-dialog'),cvDialog=$('#cv-dialog');function openDialog(d){d.showModal();document.body.classList.add('modal-open')}[projectDialog,cvDialog].forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('close',()=>document.body.classList.remove('modal-open'));d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()})});
grid.addEventListener('click',e=>{const b=e.target.closest('[data-project]');if(!b||b.matches('a[href]'))return;const p=PORTFOLIO_PROJECTS.find(p=>p.id===b.dataset.project);$('#project-content').innerHTML=mockup(p)+`<div class="case-content"><span class="eyebrow">${p.context} / ${p.category.toUpperCase()}</span><h2 id="dialog-title">${p.title}</h2><p class="copy">${p.description}</p><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="case-grid"><section><h3>Le besoin</h3><p>${p.problem}</p></section><section><h3>La réponse</h3><p>${p.solution}</p></section><section><h3>Fonctionnalités documentées</h3><ul>${p.features.map(f=>`<li>${f}</li>`).join('')}</ul></section><section><h3>Architecture</h3><p>${p.architecture}</p><div class="architecture">${p.layers.map((l,i)=>`${i?'<i>↔</i>':''}<span>${l}</span>`).join('')}</div></section><section><h3>Enjeux techniques</h3><p>${p.challenge}</p></section><section><h3>Réalisation</h3><p>${p.result}</p></section></div><p class="case-note">${p.cover?'Visuel : capture originale du projet.':'Visuel : illustration conceptuelle, capture originale à ajouter.'} ${p.github?'Dépôt GitHub disponible.':'Dépôt GitHub non fourni.'} ${p.demo?'Démonstration publique disponible.':'Démonstration publique non fournie.'} Les enjeux décrivent les besoins techniques du projet.</p><div class="case-actions">${p.github?`<a class="button secondary" href="${p.github}" target="_blank" rel="noopener noreferrer">GitHub ↗</a>`:''}${p.demo?`<a class="button secondary" href="${p.demo}" target="_blank" rel="noopener noreferrer">Live Demo ↗</a>`:''}<a class="button primary" href="mailto:lakradhamza606@gmail.com?subject=${encodeURIComponent('À propos du projet '+p.title)}">Échanger sur ce projet ↗</a></div></div>`;openDialog(projectDialog)});
$$('[data-cv]').forEach(b=>b.addEventListener('click',()=>{openDialog(cvDialog)}));
$('#terminal-form').addEventListener('submit',e=>{e.preventDefault();const input=$('#command'),cmd=input.value.trim().toLowerCase();if(!cmd)return;const replies={help:'Commandes : whoami · stack · projects · contact · clear\nBonus : sudo hire hamza',whoami:'Hamza Lakrad · EMSI, 5ᵉ année\nFutur ingénieur en Informatique et Réseaux · option Développement.',stack:'Frontend : React, JavaScript, HTML, CSS\nBackend : Django, Java/JEE, .NET, Laravel, Node.js\nDonnées : MySQL / SQL',projects:`${PORTFOLIO_PROJECTS.length} projets présentés.\nÀ la une : système de gestion des tâches — Django + React.`,contact:'Email : lakradhamza606@gmail.com\nLinkedIn : hamza-lakrad-bb9510378\nDisponible pour un stage / PFE.','sudo hire hamza':'✓ Bonne idée. Discutons de votre prochaine application !\n→ lakradhamza606@gmail.com'};$('#terminal-output').textContent=cmd==='clear'?'':`❯ ${cmd}\n${replies[cmd]||'Commande inconnue. Tapez help pour voir les commandes.'}\n`;input.value=''});
$('#copy-email').addEventListener('click',async()=>{try{await navigator.clipboard.writeText('lakradhamza606@gmail.com');$('#copy-status').textContent='Adresse e-mail copiée.';const button=$('#copy-email');button.textContent='✓ E-mail copié';button.classList.add('copied');clearTimeout(button.copyTimer);button.copyTimer=setTimeout(()=>{button.textContent='Copier mon e-mail';button.classList.remove('copied')},3000)}catch{$('#copy-status').textContent='Adresse : lakradhamza606@gmail.com'}});
const form=$('#contact-form'),fields=$$('#contact-form input, #contact-form textarea, #contact-form select');function validate(field){const value=field.value.trim();let error='';if(!value)error='Ce champ est requis.';else if(field.type==='email'&&!field.validity.valid)error='Saisissez une adresse e-mail valide.';else if(field.id==='message'&&value.length<10)error='Votre message doit contenir au moins 10 caractères.';field.setAttribute('aria-invalid',String(Boolean(error)));$(`#${field.id}-error`).textContent=error;return !error}fields.forEach(f=>{f.addEventListener('blur',()=>validate(f));f.addEventListener('input',()=>{if(f.getAttribute('aria-invalid')==='true')validate(f)})});form.addEventListener('submit',e=>{e.preventDefault();if(!fields.map(validate).every(Boolean)){fields.find(f=>f.getAttribute('aria-invalid')==='true').focus();$('#form-status').textContent='Vérifiez les champs indiqués avant de continuer.';return}const value=id=>$(id).value.trim();const body=`Bonjour Hamza,\n\n${value('#message')}\n\n${value('#name')}\n${value('#email')}`;const href=`mailto:lakradhamza606@gmail.com?subject=${encodeURIComponent(value('#subject'))}&body=${encodeURIComponent(body)}`;$('#mail-fallback').href=href;$('#mail-fallback').hidden=false;$('#form-status').textContent='Votre message est prêt. Finalisez son envoi dans votre messagerie. Si elle ne s’ouvre pas, utilisez le lien ci-dessous ou écrivez directement à mon adresse.';location.href=href});$('#year').textContent=new Date().getFullYear();
if(matchMedia('(pointer:fine)').matches&&!reduced.matches){let pending=false,x=0,y=0;document.addEventListener('pointermove',e=>{if(document.documentElement.hasAttribute('data-premium-cursor')||e.target.closest('#accueil.hero-comfort'))return;x=e.clientX;y=e.clientY;if(pending)return;pending=true;requestAnimationFrame(()=>{document.documentElement.style.setProperty('--mx',`${x}px`);document.documentElement.style.setProperty('--my',`${y}px`);pending=false})},{passive:true});grid.addEventListener('pointermove',e=>{if(grid.closest('.orbit-projects'))return;const art=e.target.closest('.art');if(!art)return;const r=art.getBoundingClientRect();art.style.setProperty('--tx',`${-((e.clientY-r.top)/r.height-.5)*4}deg`);art.style.setProperty('--ty',`${((e.clientX-r.left)/r.width-.5)*4}deg`)},{passive:true});grid.addEventListener('pointerout',e=>{const art=e.target.closest('.art');if(art&&!art.contains(e.relatedTarget)){art.style.setProperty('--tx','0deg');art.style.setProperty('--ty','0deg')}})}
